#!/usr/bin/env python3
"""Read only two fixed remaining source edges and typed metadata."""
import base64,gzip,hashlib,sys,types
sys.dont_write_bytecode=True
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='07a66142e013d9139578b99d9bc39fe1e5704eff66891ca7bb176eb5a21709cf':raise RuntimeError("HOLD_SOURCE_DIGEST")
m=types.ModuleType('remaining_edge_public_key');m.__file__='<reviewed-remaining_edge_public_key>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='7959380519eb5228bb782447c8fd43a5c495591b3007589eb3aa605fc1c51f1a':raise RuntimeError("HOLD_SOURCE_DIGEST")
m=types.ModuleType('remaining_edge_readback');m.__file__='<reviewed-remaining_edge_readback>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raise SystemExit(m.entry())
